<?php
$pageTitle='Reports';
[$scope,$scopeParams]=current_task_access_sql();
$projectId=(int)($_GET['project_id']??0);$statusFilter=(string)($_GET['status']??'');
$projectSql='SELECT p.id,p.name FROM projects p';$projectParams=[];if(!is_manager()&&user()['role']!=='site_supervisor'){$projectSql.=' WHERE EXISTS (SELECT 1 FROM tasks t WHERE t.project_id=p.id AND t.assigned_to=?)';$projectParams[]=(int)user()['id'];}$projectSql.=' ORDER BY p.name';$st=$pdo->prepare($projectSql);$st->execute($projectParams);$projects=$st->fetchAll();
$where=' WHERE 1=1';$params=[];if(!is_manager()&&user()['role']!=='site_supervisor'){$where.=' AND t.assigned_to=?';$params[]=(int)user()['id'];}if($projectId>0){$where.=' AND t.project_id=?';$params[]=$projectId;}if(in_array($statusFilter,['pending','in_progress','blocked','completed'],true)){$where.=' AND t.status=?';$params[]=$statusFilter;}
$reportSql="SELECT t.id,t.title,t.start_date,t.due_date,t.status,t.priority,t.progress_percent,p.name AS project_name,u.full_name AS assignee_name FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to $where ORDER BY p.name,t.due_date IS NULL,t.due_date";
if(($_GET['export']??'')==='csv'){
    $st=$pdo->prepare($reportSql);$st->execute($params);$rows=$st->fetchAll();
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="buildtrack-task-report-'.date('Y-m-d').'.csv"');
    $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Project','Task','Assigned To','Start Date','Due Date','Status','Priority','Progress (%)']);
    foreach($rows as $r){$vals=[$r['project_name'],$r['title'],$r['assignee_name']??'Unassigned',$r['start_date']??'',$r['due_date']??'',status_label($r['status']),ucfirst($r['priority']),(int)$r['progress_percent']];foreach($vals as &$v){$v=(string)$v;if(preg_match('/^[=+\-@\t\r]/',$v))$v="'".$v;}unset($v);fputcsv($out,$vals);}fclose($out);exit;
}
$st=$pdo->prepare($reportSql);$st->execute($params);$rows=$st->fetchAll();
$tot=count($rows);$complete=count(array_filter($rows,fn($r)=>$r['status']==='completed'));$overdue=count(array_filter($rows,fn($r)=>$r['due_date'] && $r['due_date']<date('Y-m-d') && $r['status']!=='completed'));$average=$tot?(int)round(array_sum(array_column($rows,'progress_percent'))/$tot):0;
require __DIR__ . '/../inc/header.php';
?>
<div class="page-toolbar"><p class="muted">Summaries for planning, monitoring and project review. Export the current filter as a CSV file.</p><a class="btn btn-primary" href="index.php?page=reports&export=csv&project_id=<?= $projectId ?>&status=<?= e($statusFilter) ?>">↓ Export CSV</a></div>
<section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Tasks in report</span><span class="stat-icon icon-blue">☷</span></div><div class="stat-number"><?= $tot ?></div><div class="stat-note">Matches selected filters</div></article><article class="stat-card"><div class="stat-top"><span>Completed</span><span class="stat-icon icon-green">✓</span></div><div class="stat-number"><?= $complete ?></div><div class="stat-note"><?= $tot?(int)round($complete/$tot*100):0 ?>% of report tasks</div></article><article class="stat-card"><div class="stat-top"><span>Overdue</span><span class="stat-icon icon-red">!</span></div><div class="stat-number"><?= $overdue ?></div><div class="stat-note">Unfinished past due date</div></article><article class="stat-card"><div class="stat-top"><span>Average progress</span><span class="stat-icon icon-indigo">↗</span></div><div class="stat-number"><?= $average ?>%</div><div class="stat-note">Average of listed task progress</div></article></section>
<section class="panel"><div class="panel-heading"><div><h3>Task performance report</h3><p>Use filters to focus on a project or status.</p></div></div><form method="get" class="filter-bar"><input type="hidden" name="page" value="reports"><select name="project_id"><option value="0">All accessible projects</option><?php foreach($projects as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $projectId===(int)$p['id']?'selected':'' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><?php foreach(['pending','in_progress','blocked','completed'] as $s): ?><option value="<?= e($s) ?>" <?= $statusFilter===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select><button class="btn btn-outline">Apply</button><a class="text-link" href="index.php?page=reports">Reset</a></form><?php if(!$rows): ?><div class="empty-inline">No tasks match the selected filters.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Project</th><th>Task</th><th>Assignee</th><th>Due date</th><th>Status</th><th>Priority</th><th>Progress</th></tr></thead><tbody><?php foreach($rows as $r): $late=$r['due_date'] && $r['due_date']<date('Y-m-d') && $r['status']!=='completed'; ?><tr><td><?= e($r['project_name']) ?></td><td><strong><?= e($r['title']) ?></strong></td><td><?= e($r['assignee_name']?:'Unassigned') ?></td><td class="<?= $late?'text-danger':'' ?>"><?= e(date_label($r['due_date'])) ?></td><td><span class="status status-<?= e($r['status']) ?>"><?= e(status_label($r['status'])) ?></span></td><td><span class="priority priority-<?= e($r['priority']) ?>"><?= e(ucfirst($r['priority'])) ?></span></td><td><div class="progress-line"><span style="width:<?= (int)$r['progress_percent'] ?>%"></span></div><small><?= (int)$r['progress_percent'] ?>%</small></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<div class="alert alert-info">Report totals are calculated from the tasks visible to your user role and the filters above. CSV export contains the same task-level data.</div>
<?php require __DIR__ . '/../inc/footer.php'; ?>
